const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
let free = 3;
let mostWaiting = 0;
let waitedCount = 0;
const waiting = [];

async function query() {
  if (free > 0) free--;
  else {
    waitedCount++;
    await new Promise((resolve) => { waiting.push(resolve); mostWaiting = Math.max(mostWaiting, waiting.length); });
  }
  await sleep(10);
  const next = waiting.shift();
  if (next) next();
  else free++;
}

await Promise.all(Array.from({ length: 8 }, query));
console.log(mostWaiting, waitedCount, free);

import { createInMemoryQueue, createQueueName } from "@zudojs/queue";

const wait = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
const queue = createInMemoryQueue(createQueueName("reminders"), { concurrency: 4 });
let running = 0;
let mostAtOnce = 0;
queue.process("remind", async () => {
  running++;
  mostAtOnce = Math.max(mostAtOnce, running);
  await wait(20);
  running--;
});
for (let n = 1; n <= 10; n++) await queue.add("remind", { n });
while ((await queue.getStats()).succeeded < 10) await wait(10);
console.log(mostAtOnce, (await queue.getStats()).succeeded);
await queue.close();

function copiesFor(max, checks) {
  let list = [];
  let copied = 0;
  for (let i = 0; i < checks; i++) {
    copied += list.length;
    list = list.slice();
    if (list.length < max) list.push(i);
  }
  return copied;
}

console.log(copiesFor(3, 6), copiesFor(1000, 6));

