function poolSize({ requestsPerSecond, queriesPerRequest, queryMs, processes }) {
  const busyTotal = requestsPerSecond * queriesPerRequest * (queryMs / 1000);
  const perProcess = Math.ceil(busyTotal / processes);
  return Math.max(2, Math.ceil(perProcess * 1.5));
}

