const realDb = {
  async query(sql, params) {
    if (sql.startsWith("SELECT id, assignee")) return [{ id: 1, assignee: "u-1" }, { id: 2, assignee: "u-2" }, { id: 3, assignee: "u-3" }];
    return [{ name: `User ${params[0]}` }];
  },
};

function withQueryCount(db) {
  let queries = 0;
  return {
    db: {
      query(sql, params) {
        queries += 1;
        return db.query(sql, params);
      },
    },
    count: () => queries,
  };
}

