function hotKeys(log, n) {
  const counts = new Map();
  for (const key of log) counts.set(key, (counts.get(key) ?? 0) + 1);
  return [...counts]
    .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))
    .slice(0, n)
    .map(([key, count]) => `${key} ${count}`);
}

