  for (const [key, limit] of Object.entries(budget)) {
    const value = measured[key];
    const pass = value <= limit;
    if (!pass) ok = false;
    console.log(`${pass ? "PASS" : "FAIL"}  ${name} ${key} ${value} <= ${limit}`);
  }
  return ok;
}

