function createBoundedMap(max) {
  const entries = new Map();
  return {
    get(key) {
      if (!entries.has(key)) return undefined;
      const value = entries.get(key);
      entries.delete(key);
      entries.set(key, value);
      return value;
    },
    set(key, value) {
      entries.delete(key);
      entries.set(key, value);
      if (entries.size > max) entries.delete(entries.keys().next().value);
    },
    size: () => entries.size,
  };
}

const quotes = createBoundedMap(3);
quotes.set("rice", 950_000);
quotes.set("beans", 420_000);
quotes.set("oil", 610_000);
quotes.get("rice");
quotes.set("salt", 90_000);
